	@Test
	void callbackFailureRetainsCleanupFailuresAndReleasesEverything() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		RuntimeException callbackFailure = new RuntimeException("callback failure");
		RuntimeException sourceFailure = new RuntimeException("source cleanup failure");
		RuntimeException stateFailure = new RuntimeException("state cleanup failure");
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicInteger sourceCloses = new AtomicInteger();
		AtomicInteger stateCloses = new AtomicInteger();
		context.nativeState(new Object(), () -> (AutoCloseable) () -> {
			stateCloses.incrementAndGet();
			throw stateFailure;
		});
		Stub source = new Stub() {
			@Override
			public boolean requestCancellation() {
				entered.countDown();
				await(release);
				throw callbackFailure;
			}

			@Override
			public void close() {
				sourceCloses.incrementAndGet();
				throw sourceFailure;
			}
		};
		NativeContextClosingIteration result = new NativeContextClosingIteration(source, context);
		try (var workers = Executors.newFixedThreadPool(2);
				AutoCloseable cleanup = () -> {
					release.countDown();
					result.close();
				}) {
			var request = workers.submit(result::requestCancellation);
			assertTrue(entered.await(5, TimeUnit.SECONDS));
			workers.submit(result::close).get(5, TimeUnit.SECONDS);
			assertFalse(context.isClosed());
			release.countDown();
			ExecutionException thrown = assertThrows(ExecutionException.class, () -> request.get(5, TimeUnit.SECONDS));
			assertSame(callbackFailure, thrown.getCause());
			assertTrue(contains(callbackFailure, sourceFailure), "the source cleanup error must remain visible");
			assertTrue(contains(callbackFailure, stateFailure), "the context cleanup error must remain visible");
			assertEquals(1, sourceCloses.get());
			assertEquals(1, stateCloses.get());
			assertTrue(context.isClosed());
		}
	}

