	@Test
	void transitiveOwnersRemainLiveAndCloseAfterTheirDependents() throws Exception {
		NativeExecutionContext root = new NativeExecutionContext();
		NativeExecutionContext term = new NativeExecutionContext(root);
		NativeExecutionContext frame = new NativeExecutionContext(term, EmptyBindingSet.getInstance(), true);
		NativeExecutionContext child = new NativeExecutionContext(frame);
		List<String> order = new ArrayList<>();
		root.nativeState(new Object(), () -> (AutoCloseable) () -> order.add("root"));
		term.nativeState(new Object(), () -> (AutoCloseable) () -> {
			assertFalse(root.isClosed(), "term cleanup needs the query scope");
			order.add("term");
		});
		frame.nativeState(new Object(), () -> (AutoCloseable) () -> {
			assertFalse(term.isClosed(), "frame cleanup needs its borrowed term owner");
			order.add("frame");
		});
		child.nativeState(new Object(), () -> (AutoCloseable) () -> {
			assertFalse(frame.isClosed(), "child cleanup needs its borrowed frame owner");
			order.add("child");
		});
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		Stub source = new Stub() {
			@Override
			public boolean requestCancellation() {
				entered.countDown();
				await(release);
				return true;
			}

			@Override
			public void close() {
			}
		};
		NativeContextClosingIteration result = new NativeContextClosingIteration(source, child);
		try (var workers = Executors.newFixedThreadPool(2);
				AutoCloseable cleanup = () -> {
					release.countDown();
					result.close();
					frame.close();
					term.close();
					root.close();
				}) {
			var request = workers.submit(result::requestCancellation);
			assertTrue(entered.await(5, TimeUnit.SECONDS));
			result.close();
			frame.close();
			term.close();
			root.close();
			assertFalse(root.isClosed());
			assertFalse(term.isClosed());
			assertFalse(frame.isClosed());
			assertFalse(child.isClosed());
			assertTrue(order.isEmpty());
			release.countDown();
			assertTrue(request.get(5, TimeUnit.SECONDS));
			assertEquals(List.of("child", "frame", "term", "root"), order);
		}
	}

	@Test
	void contextCleanupCanReenterCarrierWhileSourceCloseWaitsForIt() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		CountDownLatch sourceEntered = new CountDownLatch(1);
		CountDownLatch sourceMayReturn = new CountDownLatch(1);
		CountDownLatch contextEntered = new CountDownLatch(1);
		CountDownLatch reentryReturned = new CountDownLatch(1);
		AtomicReference<Thread> contextThread = new AtomicReference<>();
		AtomicReference<NativeContextClosingIteration> owner = new AtomicReference<>();
		AtomicBoolean sourceFinished = new AtomicBoolean();
		AtomicInteger sourceCloses = new AtomicInteger();
		AtomicInteger stateCloses = new AtomicInteger();
		context.nativeState(new Object(), () -> (AutoCloseable) () -> {
			stateCloses.incrementAndGet();
			contextThread.set(Thread.currentThread());
			contextEntered.countDown();
			try {
				owner.get().close();
				assertFalse(sourceFinished.get(), "the reentrant request must not finish another owner's source close");
				reentryReturned.countDown();
			} finally {
				sourceMayReturn.countDown();
			}
		});
		Stub source = new Stub() {
			@Override
			public boolean requestCancellation() {
				return false;
			}

			@Override
			public void close() {
				sourceCloses.incrementAndGet();
				sourceEntered.countDown();
				await(sourceMayReturn);
				sourceFinished.set(true);
			}
		};
		NativeContextClosingIteration result = new NativeContextClosingIteration(source, context, false);
		owner.set(result);
		try (var workers = Executors.newFixedThreadPool(2);
				AutoCloseable cleanup = () -> {
					sourceMayReturn.countDown();
					result.close();
					context.close();
				}) {
			var sourceClose = workers.submit(result::close);
			assertTrue(sourceEntered.await(5, TimeUnit.SECONDS));
			var contextClose = workers.submit(context::close);
			assertTrue(contextEntered.await(5, TimeUnit.SECONDS));
			awaitState(() -> reentryReturned.getCount() == 0 || blocked(contextThread.get()),
					"context cleanup neither reentered nor waited for source cleanup");
			assertEquals(0, reentryReturned.getCount(), "the context owner cannot wait for its own cleanup dependency");
			sourceClose.get(5, TimeUnit.SECONDS);
			contextClose.get(5, TimeUnit.SECONDS);
			assertTrue(sourceFinished.get());
			assertTrue(context.isClosed());
			assertEquals(1, sourceCloses.get());
			assertEquals(1, stateCloses.get());
		}
	}

	@Test
	void concurrentCloseWaitsForPhysicalCleanup() throws Exception {
		assertConcurrentCloseOutcome(false);
	}

	@Test
	void concurrentCloseObservesPhysicalCleanupFailure() throws Exception {
		assertConcurrentCloseOutcome(true);
	}

	private static void assertConcurrentCloseOutcome(boolean fail) throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		CountDownLatch closeEntered = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		CountDownLatch secondEntered = new CountDownLatch(1);
		AtomicReference<Thread> secondThread = new AtomicReference<>();
		RuntimeException failure = new RuntimeException("physical close failed");
		AtomicInteger sourceCloses = new AtomicInteger();
		Stub source = new Stub() {
			@Override
			public boolean requestCancellation() {
				return false;
			}

			@Override
			public void close() {
				sourceCloses.incrementAndGet();
				closeEntered.countDown();
				await(releaseClose);
				if (fail) {
					throw failure;
				}
			}
		};
		NativeContextClosingIteration result = new NativeContextClosingIteration(source, context);
		try (var workers = Executors.newFixedThreadPool(2);
				AutoCloseable cleanup = () -> {
					releaseClose.countDown();
					result.close();
				}) {
			var first = workers.submit(result::close);
			assertTrue(closeEntered.await(5, TimeUnit.SECONDS));
			var second = workers.submit(() -> {
				secondThread.set(Thread.currentThread());
				secondEntered.countDown();
				result.close();
			});
			assertTrue(secondEntered.await(5, TimeUnit.SECONDS));
			awaitState(() -> second.isDone() || blocked(secondThread.get()),
					"second close neither returned nor waited for physical cleanup");
			assertFalse(second.isDone(), "the racing closer must not pass unfinished cleanup");
			releaseClose.countDown();
			if (fail) {
				assertSame(failure,
						assertThrows(ExecutionException.class, () -> first.get(5, TimeUnit.SECONDS)).getCause());
				assertSame(failure,
						assertThrows(ExecutionException.class, () -> second.get(5, TimeUnit.SECONDS)).getCause());
			} else {
				first.get(5, TimeUnit.SECONDS);
				second.get(5, TimeUnit.SECONDS);
			}
			assertEquals(1, sourceCloses.get());
			assertTrue(context.isClosed());
		}
	}

	private static boolean blocked(Thread thread) {
		return thread != null
				&& (thread.getState() == Thread.State.WAITING || thread.getState() == Thread.State.BLOCKED);
	}

	private static void awaitState(BooleanSupplier condition, String message) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (!condition.getAsBoolean()) {
			if (System.nanoTime() >= deadline) {
				throw new AssertionError(message);
			}
			Thread.onSpinWait();
		}
	}

	private static boolean contains(Throwable root, Throwable expected) {
		if (root == expected) {
			return true;
		}
		return Arrays.stream(root.getSuppressed()).anyMatch(suppressed -> contains(suppressed, expected));
	}

	private static void await(CountDownLatch latch) {
		boolean interrupted = false;
		while (true) {
			try {
				latch.await();
				break;
			} catch (InterruptedException failure) {
				interrupted = true;
			}
		}
		if (interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	private abstract static class Stub implements CloseableIteration<BindingSet>, CooperativeCancellation {
		@Override
		public boolean hasNext() {
			return false;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}
	}
